    body: "教育支援センター（適応指導教室）とは、不登校の状態にある児童生徒に対し、学校生活への復帰や社会的自立を支援するために、教育委員会などが学校以外の場所に設置する公的な施設です。文部省（現・文部科学省）の学校不適応対策事業として1990年に「適応指導教室」の名称で導入され、2003年からは「教育支援センター」という名称も用いられるようになりました。\n\n在籍校と連携を取りながら、個別カウンセリング、小集団での活動、教科指導などを組織的・計画的に行い、児童生徒の情緒の安定や基礎学力の補充、集団生活への適応を支えます。公的機関であるため、多くの場合利用料はかかりません。\n\n一定の要件を満たせば、教育支援センターへの通所を在籍校の出席日数として扱うことができ、不登校児童生徒の学びの場を保障する仕組みの一つとして位置づけられています。",
