    body: "いじめの重大事態とは、いじめ防止対策推進法第28条に規定される、いじめにより児童生徒の心身や学校生活に極めて大きな影響が生じたと認められる事態を指します。同法は重大事態を二つの類型に分けて定義しています。\n\n一つは、いじめにより児童生徒の生命、心身または財産に重大な被害が生じた疑いがあると認めるとき（いわゆる1号重大事態）で、自殺や重い傷害、金品の重大な被害などが該当し得ます。もう一つは、いじめにより相当の期間、学校を欠席することを余儀なくされている疑いがあると認めるとき（2号重大事態）で、目安として年間30日程度の欠席が一つの基準とされています。\n\n重大事態が発生した場合、学校の設置者または学校は、速やかに第三者を含む調査組織を設けて事実関係を明確にするための調査を行い、被害児童生徒・保護者への情報提供や再発防止策の検討を行うことが法律上求められています。",
