      "学校教育法第11条により禁止されている、児童生徒の身体に対する侵害や、肉体的苦痛を伴う懲戒。教員による懲戒権とは明確に区別される。",
    body: "体罰とは、学校教育法第11条により校長・教員に禁止されている、児童生徒の身体に対する侵害（殴る、蹴るなど）や、正座・直立などを長時間強制するといった肉体的苦痛を伴う懲戒行為を指します。同条は教員による懲戒権を認める一方で、体罰を加えることを明確に禁じています。\n\n文部科学省が示す参考事例によれば、放課後に教室に残留させる、授業中に起立させる、学習課題や清掃活動を課すといった、身体に対する侵害や肉体的苦痛を伴わない指導は懲戒として許容される一方、殴打や長時間の正座強制などは体罰に該当するとされています。何が体罰にあたるかは、個々の状況を総合的に考慮して判断されます。\n\n体罰は児童生徒の心身に深刻な影響を及ぼすだけでなく、指導への不信感や問題行動の悪化を招く危険性が指摘されており、暴力によらない生徒指導の実現に向けて、教職員研修や校内体制の整備が進められています。",
