    body: "出席停止とは、学校教育法第35条に基づき、市町村の教育委員会が、他の児童生徒に傷害や心身の苦痛、財産上の損失を与える行為、施設・設備を損壊する行為、授業などの教育活動の実施を妨げる行為を繰り返すなど性行不良であって、他の児童生徒の教育に妨げがあると認める児童生徒について、その保護者に対して命じることができる措置です。\n\n個々の児童生徒に対する制裁として行われる懲戒とは異なり、出席停止は学校の秩序を維持し、他の児童生徒が安心して教育を受ける権利を保障するという観点から設けられている点が特徴です。命令に先立ち、教育委員会は保護者の意見聴取や理由・期間を記した文書の交付を行うことが定められています。\n\n出席停止は義務教育段階の児童生徒を対象とする制度であり、退学のように学籍そのものを失わせるものではありません。運用にあたっては、当該児童生徒への学習支援や、出席停止に至った背景への理解と再発防止に向けた指導・支援を並行して行うことが求められています。",
