    reading: "すくーるかーすと",
    kana: "す",
    categories: ["guidance", "sociology"],
    summary:
      "主に中学校・高校のクラス内で日常のコミュニケーションを通じて形成される、生徒間の暗黙の序列・グループ間の力関係を指す用語。",
    body: "スクールカーストとは、主に中学校や高校のクラス内で、生徒同士の日常的なコミュニケーションを通じて形成される暗黙の序列やグループ間の力関係を指す和製英語です。インドのカースト制度になぞらえた呼称で、上位・中位・下位の層が「一軍・二軍・三軍」などと俗に表現されることもあります。\n\nこの序列は、学力や運動能力といった従来の学校的な評価軸よりも、自己主張の強さやコミュニケーション能力、周囲からの人気度など、教室内の対人関係の力学によって規定される傾向が強いとされます。2000年代以降、教育社会学の分野でも研究対象として取り上げられるようになり、鈴木翔による調査研究などが知られています。\n\nスクールカーストにおける立場の固定化は、下位に置かれた生徒の自己肯定感の低下や、いじめの発生・深刻化の温床となる可能性が指摘されています。教員が学級内の人間関係の力学を把握し、特定の生徒に序列や役割が固定化しないよう学級経営上配慮することの重要性が論じられています。",
