    body: "生徒指導主事とは、学校教育法施行規則第70条に基づき中学校に置くものとされる（高等学校等にも準用される）役職で、指導教諭または教諭がその任にあたります。同条は「生徒指導主事は、校長の監督を受け、生徒指導に関する事項をつかさどり、当該事項について連絡調整及び指導、助言に当たる」と定めています。\n\n生徒指導主事は、校務分掌における生徒指導組織の中心として位置づけられ、学校全体の生徒指導を場当たり的にではなく組織的・計画的に運営していく責任を担います。具体的には、生徒指導方針の策定への関与、校内の生徒指導委員会等の運営、各学年・各教科担任間の連絡調整、家庭・地域との連携窓口としての役割などを果たします。\n\nいじめ、不登校、問題行動など生徒指導上の課題が複雑化・多様化する中、生徒指導主事には全教職員や保護者・地域から情報を収集し児童生徒の実態を的確に把握した上で、校長を補佐しながらチームとしての生徒指導体制を機能させる調整役としての役割が一層求められています。",
