    body: "教育機会確保法とは、正式名称を「義務教育の段階における普通教育に相当する教育の機会の確保等に関する法律」（平成28年法律第105号）といい、2016年（平成28年）の臨時国会で議員立法として成立した法律です。フリースクール関係者による制度上の地位安定を求める働きかけが立法の発端となり、その後、夜間中学関係者の運動も合流して成立に至りました。\n\nこの法律は、不登校児童生徒が学校を休むことを必ずしも問題行動と捉えず、その状況に応じた休養の必要性を認めた上で、学校以外の多様な学びの場（フリースクールや教育支援センターなど）における学習活動の重要性を位置づけている点に大きな特徴があります。国や地方公共団体には、不登校児童生徒の状況に応じた必要な支援を行う責務が定められています。\n\nまた、この法律は義務教育を修了できなかった人が学び直す場である夜間中学の設置促進についても規定しており、不登校対応と夜間中学の拡充という二つの側面を持つ法律として、その後の不登校施策や教育支援センターの運用にも影響を与えています。",
