    body: "学びの多様化学校は、不登校児童生徒の実態に配慮して、標準の教育課程によらない特別の教育課程を編成・実施できる学校です。従来は不登校特例校と呼ばれていましたが、文部科学省の「COCOLOプラン」を受けて2023年に子どもの目線に立った名称へ改称されました。\n\n授業時数の弾力化や登校時間の調整、体験活動を重視したカリキュラムなど、一人一人のペースに合わせた学びを可能にする点が特徴です。公立・私立の双方で設置が進んでおり、設置校数は年々増加しています。\n\n学びの多様化学校は、通常の学級への復帰のみを目標とせず、多様な学びの場を保障する考え方に基づいています。地域の教育支援センターや相談機関とも連携しながら、不登校児童生徒の学習権を保障する仕組みの一つとなっています。",
