    body: "少年法は、非行のある少年の健全な育成を期し、性格の矯正及び環境の調整に関する保護処分を行うことを目的とする法律です。成人の刑事手続とは異なり、少年の可塑性を重視した保護主義の立場に立っている点が特徴です。\n\n学校は、生徒が事件を起こした場合であっても、家庭裁判所の審判や少年鑑別所への収容などの手続きと並行して、生徒の学びや立ち直りを支える教育的役割を担います。少年審判の内容は原則非公開とされ、学校もプライバシー保護に配慮した対応が求められます。\n\n非行のあった生徒の学校復帰にあたっては、保護観察官や少年鑑別所の法務教官、児童相談所などの関係機関と情報を共有し、ケース会議を通じて再発防止と社会復帰支援を組織的に進めることが重要です。",
