    body: "自傷行為とは、リストカットなど自らの身体を意図的に傷つける行為で、多くの場合、死ぬことを目的とせず、耐えがたい心理的苦痛を一時的に緩和するための対処行動として行われます。思春期の児童生徒に少なからず見られる問題です。\n\n発見時には、行為そのものを叱責したり驚きを強く示したりするのではなく、まず安全を確保した上で、本人を責めない姿勢で話を聴くことが重要とされています。自傷行為の背景には家庭環境や対人関係の悩みなど複雑な要因が絡んでいることが多いためです。\n\n自傷行為は自殺のリスク要因の一つでもあるため、養護教諭やスクールカウンセラーと連携し、必要に応じて医療機関へつなぐことが求められます。学級担任一人で抱え込まず、校内チームで継続的に見守る体制が重要です。",
