    summary:
      "非行少年に対して施設収容によらず、社会の中で保護観察官・保護司の指導監督や補導援護を受けさせながら更生を図る少年法上の保護処分。学校に在籍したまま処分を受けるケースも多く、学校との連携が重要となる。",
    body: "保護観察は、家庭裁判所の審判により非行少年に言い渡される保護処分の一つで、少年院等の施設に収容せず、少年を家庭や地域社会に置いたまま、保護観察官及び保護司の指導監督(遵守事項を守らせ、生活状況を把握する)と補導援護(就学・就労の援助や生活指導)を通じて更生を図る制度である。少年法上の保護処分には、保護観察のほか、児童自立支援施設・児童養護施設送致、少年院送致があり、保護観察は施設収容を伴わない最も社会内処遇に近い処分として位置づけられる。\n\n保護観察に付された少年は、保護観察所の実施計画に基づき、定期的に保護司と面接し生活状況を報告するとともに、一般遵守事項(健全な生活態度の保持、保護観察官・保護司の指導への服従など)や個別の特別遵守事項を守ることが求められる。学齢期・在学中の少年が保護観察処分を受けた場合、多くは学校に通いながら並行して保護観察を受けることになるため、学校(担任、生徒指導主事、スクールソーシャルワーカー等)と保護観察所・保護司との情報共有や連携が、学業の継続や再非行防止の観点から重要となる。\n\n学校現場においては、保護観察中であることのみをもって特別視・排除するのではなく、当該生徒の学びの継続や人間関係の再構築を支える視点が求められる。近年は、非行防止のための地域における立ち直り支援の一環として、保護司や更生保護サポートセンター、学校、地域の関係機関が連携する取組も進められている。",
    relatedSlugs: ["hiko-shonen-bunrui", "jido-jiritsu-shien-shisetsu", "junkai-sodan"],
