    categories: ["guidance"],
    summary:
      "家庭裁判所の観護措置決定により送致された少年を収容し、医学・心理学・教育学等の専門的知見に基づき資質の鑑別を行う法務省所管の施設。原則4週間以内の収容で、審判に向けた処遇選択の資料を作成する。",
    body: "少年鑑別所は、非行のあった少年について家庭裁判所が観護措置決定を行った場合に、少年を収容し、その資質(性格・非行の原因・背景など)を医学・心理学・教育学・社会学その他の専門的知見に基づいて鑑別する法務省所管の施設である。収容期間は原則2週間以内で、必要に応じて更新され最長4週間(特に必要な場合は8週間)まで延長されうる。少年院とは異なり、少年鑑別所はあくまで審判前の資質鑑別・観護のための施設であり、処分(保護観察・少年院送致等)が確定した後に収容される矯正教育施設ではない点が大きな違いである。\n\n少年鑑別所での鑑別の結果は「鑑別結果通知書」としてまとめられ、家庭裁判所が保護処分を決定する際の重要な資料となるほか、その後の保護観察や少年院での処遇にも活用される。また、少年鑑別所は法務少年支援センターとしての機能も担っており、非行や問題行動に悩む学校・保護者・本人からの相談を受け付け、心理検査や助言を行うなど、地域社会に開かれた相談機関としての役割も果たしている。\n\n在学中の生徒が少年鑑別所に収容された場合、学校は出席の取り扱いや学習の遅れへの配慮、退所後の学校復帰支援について、家庭裁判所調査官や保護者と連携しながら対応する必要がある。学校が法務少年支援センターの相談機能を活用し、生徒指導上の課題について専門的な助言を受けることも可能である。",
    relatedSlugs: ["hogo-kansatsu", "hiko-shonen-bunrui", "jido-jiritsu-shien-shisetsu"],
