    body: "認知行動療法は、感情や行動が出来事そのものではなく、その受け止め方である認知に左右されるという考え方に立つ心理療法です。1960年代にアーロン・ベックが提唱した認知療法と、学習理論に基づく行動療法が統合されて発展しました。固定的なスキーマから生じる「自動思考」を取り上げ、その偏りを見直すことで症状の改善を目指します。うつ病や不安症の治療で効果が検討されてきました。\n\n代表的な技法に、思考と気分を書き出して根拠を点検するコラム法などの認知再構成、苦手な場面に段階的に慣れていく曝露、活動を増やす行動活性化があります。「すべて失敗だ」「みんなに嫌われている」といった極端な考え方に気づき、別の見方を試す練習が中心です。なお、カウンセリング関連の略称「CBT」は、評価分野で使うコンピュータ使用型テストの略称と同じなので、文脈で区別が必要です。\n\n学校では、不安の強い子、怒りを抑えにくい子、ストレスへの対処が苦手な子への支援や、学級全体で行う心の健康教育に取り入れられています。アンガーマネジメントやストレスマネジメント教育とも重なる内容です。ただし本格的な治療は専門家が担うもので、教師は技法を取り入れる際に、子どもの負担や守秘に配慮し、スクールカウンセラーや医療機関と役割を分けることが大切です。",
