      "エリスが1955年に提唱した心理療法。感情の原因は出来事ではなく信念にあるとし、非合理的な信念を論駁して考え方を変える。",
    body: "論理療法は、アメリカの臨床心理学者アルバート・エリスが1955年に提唱した心理療法で、のちに理性感情行動療法（REBT）と呼ばれるようになりました。ベックの認知療法より前に認知に焦点を当てた、認知行動療法の先駆けとされています。落ち込みや怒りといった感情的な混乱は、出来事そのものではなく、それをどう信念として受け止めるかによって生じると考えます。\n\n中心となるのがABC理論です。出来事（A）に対する信念（B）が結果としての感情や行動（C）を決める、という図式で、問題となるのは「失敗してはならない」「みんなに好かれるべきだ」といった「～べき」型の非合理的な信念（イラショナル・ビリーフ）です。のちにD（論駁）、E（効果的な新しい信念）、F（望ましい感情や行動）が加えられ、非合理的な信念を問い直し、柔軟で現実的な信念に置き換えていく手順が示されました。\n\n学校では、テストの失敗や友人関係のつまずきで強く落ち込む生徒への面接や、完璧主義的な考えを和らげる指導の手がかりになります。「あなたの考えは間違っている」と否定すると関係を損ねるため、問いかけで本人に気づかせる姿勢が求められます。構成的グループエンカウンターなどの集団活動の中で、考え方の幅を広げる学習として取り入れる実践もあります。",
