    body: "3段階の心理教育的援助サービスは、石隈利紀が1999年の『学校心理学』で示した、学校心理学の基本的な枠組みです。学校教育を、子どもが学習面、心理・社会面、進路面、健康面で直面する課題を支える「心理教育的援助サービス」ととらえ、援助ニーズの大きさに応じて三つの段階に整理しました。\n\n一次的援助サービスは、すべての子どもに共通する基本的なニーズに応えるもので、わかりやすい授業、安全で支持的な学級づくり、レジリエンスやキャリア発達を促す教育などが当たります。二次的援助サービスは、学習の遅れや人間関係の苦戦など、一部の子どもが示す付加的なニーズへの早期の支援です。三次的援助サービスは、不登校、いじめ、発達障害などに関連する特別なニーズをもつ特定の子どもへの個別の援助を指します。一次が二次・三次の土台となり、二次・三次で効果のあった方法を一次に取り入れるという循環も強調されます。\n\nこの枠組みは、マネジメント委員会、コーディネーション委員会、個別の援助チームという三層の組織による学校のチーム支援とも対応しています。生徒指導の重層的支援構造や、チーム学校の考え方とも通じ、教師、スクールカウンセラー、保護者などが役割を分担して一人の子どもを支える発想の基礎になっています。",
