    body: "ライフ・キャリア・レインボーは、アメリカのキャリア心理学者ドナルド・スーパーが、1980年の論文「キャリア発達へのライフスパン・ライフスペース・アプローチ」などで示したモデルです。キャリアを職業の経歴だけでなく、生涯にわたる役割の組み合わせとしてとらえます。横軸の「ライフスパン」には、成長、探索、確立、維持、下降（解放）の五つのライフステージが置かれます。\n\n縦軸の「ライフスペース」には、子ども、学生、余暇人、市民、職業人、配偶者、家庭人、親といった役割が虹の帯のように描かれ、年金生活者を加えて九つの役割とする整理もあります。これらの役割は、家庭、学校、職場、地域という場面で演じられ、時期によって各役割の比重が変わります。個人がどの役割をどれだけ重く受け止めているかを一枚の図で確認できます。\n\n日本のキャリア教育でも、キャリアを「人が生涯の中で様々な役割を果たす中で、自分らしい生き方を実現していく過程」ととらえる考え方の背景になっています。生徒に自分の虹を描かせる授業は、今の自分が担う役割に気づき、将来の役割の組み合わせを考える活動として使われます。職業選択だけに目を向けがちな進路指導を、生き方全体の設計へ広げる視点を与えてくれます。",
