    body: "計画的偶発性理論（プランド・ハップンスタンス・セオリー）は、スタンフォード大学のジョン・クランボルツらが1999年に発表したキャリア理論です。個人のキャリアは、事前の計画どおりに決まるよりも、予期しない出来事や出会いに大きく左右されるという調査や経験を出発点に、その偶然をただ待つのではなく、自ら行動して引き寄せ、活かす姿勢を提案しました。\n\n偶然の出来事を好機に変える人の行動特性として、次の五つが挙げられます。新しいことに関心をもち続ける「好奇心」、失敗しても努力を続ける「持続性」、物事を前向きにとらえる「楽観性」、こだわりを手放して信念や行動を変えられる「柔軟性」、結果が不確実でも行動する「冒険心」です。これらは生まれつきの資質ではなく、経験の中で伸ばせる態度とされます。\n\n学校のキャリア教育では、早い段階で将来の夢を一つに決めさせることへの偏りを和らげ、「やりたいことが見つからない」と悩む生徒を支える視点になります。興味の幅を広げる体験活動や、失敗から学ぶ経験を重視する根拠にもなります。ただし、行き当たりばったりを勧める理論ではなく、日々の小さな行動の積み重ねが偶然を呼び込むという点が要点です。",
