    body: "基礎的・汎用的能力は、2011年1月の中央教育審議会答申「今後の学校におけるキャリア教育・職業教育の在り方について」で示された、社会的・職業的自立に向けて必要な基盤となる能力です。仕事に就くことに焦点をあて、実際の行動に表れるという観点から、四つの能力に整理されました。従来、キャリア教育で用いられていた「4領域8能力」に代わるものと位置づけられています。\n\n四つの能力は、「人間関係形成・社会形成能力」「自己理解・自己管理能力」「課題対応能力」「キャリアプランニング能力」です。たとえば人間関係形成・社会形成能力は、相手の意見を聴いて自分の考えを伝え、他者と協力して社会に参画する力、キャリアプランニング能力は、将来設計や選択、行動と改善を重ねる力とされます。これらは、基礎的・基本的な知識・技能、論理的思考力、意欲・態度や価値観などと相まって働くとされています。\n\n学校では、特別活動を要としつつ各教科等の学びを通じて、これらの能力をバランスよく育てることが求められます。小学校から高校まで取り組みを積み上げ、キャリア・パスポートで学びの変化を振り返る活動とも結びつきます。特定の能力に偏らず、系統的に育てるための共通の物差しとして活用されています。",
