    body: "地域若者サポートステーション（通称サポステ）は、働くことに悩みを抱える若者を対象に、就労に向けた相談や支援を行う機関です。厚生労働省が委託し、若者支援の実績やノウハウをもつ民間団体などが運営しています。全都道府県に設置され、2025年4月時点で全国179か所とされています。ニートなど仕事に就いていない若者や、そのご家族が主な対象です。\n\n対象年齢は15歳から49歳で、学生ではなく、働くことを目指す人が中心です。キャリアコンサルタントなどによる相談、コミュニケーション講座や職場体験、ジョブトレーニングを通じて、職業的自立に向けて段階的に支援します。高校中退者や、不登校のまま卒業して進路が決まらなかった若者へのアウトリーチ支援を行う自治体もあります。\n\n教育の視点では、学校を離れた後に支援が途切れないようにする「切れ目のない支援」の出口の一つです。学校は在学中から進路未決定や中退の見込みの生徒について、サポステや地域の若者支援機関と情報を共有し、卒業後もつながれるようにしておくことが望まれます。高校中退や不登校、ひきこもりの問題とも深く関わります。",
