    body: "校内教育支援センターは、学級での学習や生活が難しい児童生徒が、学校内の別の部屋で落ち着いて過ごし、自分のペースで学ぶための場です。「スペシャルサポートルーム（SSR）」などとも呼ばれ、校内フリースクールや別室登校の仕組みを整えたものです。不登校になる前の段階や、登校はできるが教室に入れない子ども、教室に戻る途中の子どもの居場所になります。\n\n文部科学省はCOCOLOプランの中で、校内教育支援センターの設置促進を施策の柱の一つに挙げ、学習指導員等の配置の充実とあわせて予算を計上しました。担当の教職員や支援員が見守り、学習の支援や相談を行い、必要に応じてスクールカウンセラーやスクールソーシャルワーカーと連携します。市町村が運営する教育支援センター（適応指導教室）とは、校内にあることで通いやすく、担任や学級との連絡が取りやすい点で異なります。\n\n運営上の留意点は、教室に戻すことだけを目的にしないことです。本人が安心して過ごせる環境をつくり、学習の遅れを防ぎながら、将来の社会的自立につなげるという視点が必要です。出席扱いや評価の取り扱い、在籍学級の教員との連携、他の子どもへの説明のしかたなどを、学校として明確にしておく必要があります。",
