    slug: "futoko-shien-no-arikata-2019",
    title: "「不登校児童生徒への支援の在り方について」（2019年通知）",
    reading: "ふとうこうじどうせいとへのしえんのありかたについて",
    kana: "ふ",
    categories: ["guidance", "system"],
    summary:
      "2019年10月25日に文部科学省が出した通知。登校という結果のみを目標とせず、社会的自立を目指す支援へと不登校対応の方針を転換した。",
    body: "「不登校児童生徒への支援の在り方について」は、文部科学省初等中等教育局長が2019年10月25日に出した通知です。不登校児童生徒数が高い水準で推移している状況を生徒指導上の喫緊の課題と位置づけたうえで、それまでの複数の通知を整理し、廃止しました。2016年に施行された教育機会確保法の趣旨を踏まえた内容になっています。\n\n通知の基本的な考え方は、支援の視点として、「学校に登校する」という結果のみを目標にするのではなく、児童生徒が自らの進路を主体的にとらえて、社会的に自立することを目指す必要がある、というものです。また、児童生徒によっては、不登校の時期が休養や自分を見つめ直す等の積極的な意味をもつことがあるとも述べられています。不登校をやみくもに問題行動と判断してはならないという姿勢が示されました。\n\nこの通知は、学校外の施設（教育支援センター、フリースクールなど）や、ICTを活用した学習活動の出席扱い、学習の評価の取り扱いなどにも関わります。登校を促す働きかけが本人を追い詰めることがあるという反省に立ち、本人や保護者の思いを受け止め、学校・家庭・関係機関が連携して支援する方向を示しました。その後のCOCOLOプランにも通じる、現在の不登校支援の基本方針です。",
