    body: "「児童生徒の問題行動・不登校等生徒指導上の諸課題に関する調査」は、文部科学省が生徒指導施策の参考とするために毎年実施している調査です。調査項目には、暴力行為、いじめ、長期欠席（不登校を含む）、高等学校における中途退学などが含まれます。対象期間は前年4月から3月までの1年間で、結果は例年秋、おおむね10月ごろに公表されます。令和5年度分は2024年10月31日に発表されました。\n\nこの調査で、いじめの認知件数や不登校児童生徒数の推移が全国的に把握されます。令和5年度は小・中学校の不登校児童生徒数が10年連続で増加し、過去最多となりました。いじめの「認知件数」は学校の積極的な把握の姿勢を反映するため、数が増えることが必ずしも悪化を意味しない点に注意が必要です。調査結果は、いじめの重大事態や自殺の状況の把握にも使われます。\n\n調査名にある「問題行動」という語は、不登校を問題行動と誤解させかねないという批判があります。文部科学省は2019年の通知で不登校を問題行動と判断してはならないと明記しており、調査の位置づけをめぐる議論は続いています。教員は、統計の数字をそのままの傾向と受け取らず、背景にある子ども一人ひとりの状況を丁寧に見る視点が大切です。",
