    body: "生命（いのち）の安全教育は、子どもたちが性暴力の加害者にも被害者にも傍観者にもならないよう、生命の尊さや自分と相手を大切にすることを学ぶ教育です。2020年6月に関係府省会議が決定した「性犯罪・性暴力対策の強化の方針」に、教育・啓発の強化の一つとして盛り込まれ、文部科学省が内閣府と連携して教材と指導の手引きを作成しました。\n\n教材は、幼児期から高校生等までの発達段階に応じて用意され、障害の状態に応じた工夫も示されています。「水着で隠れる部分（プライベートゾーン）」の学習や、同意の考え方、SNS等を通じた被害の防止、被害に遭ったときに相談する方法などが段階的に扱われます。教材は文部科学省のウェブサイトで公開され、近年も改訂が重ねられています。\n\n2022年12月に改訂された『生徒指導提要』にも、実施が盛り込まれました。子どもが被害を打ち明けられるよう、教師や保護者が話を受け止める姿勢と、スクールカウンセラーや関係機関との連携が重要です。自分の安全だけでなく、他者の境界線を尊重することを学ぶ点で、人権教育や性教育とも結びつく取り組みです。",
    relatedSlugs: ["seito-shido-teiyo", "sei-kyoiku", "school-counselor", "jinken-kyoiku"],
    isCanonical: true,
    tags: ["性暴力防止", "人権", "安全教育"],
