    body: "ライフスキルとは、日常生活で出会う要求や困難に、建設的かつ効果的に対処するための心理社会的能力のことです。世界保健機関（WHO）が1993年に提唱し、薬物使用や危険な性行動などの問題行動を予防する心理社会的発達のアプローチとして広まりました。ライフスキル教育は、これらの能力を教室での学習を通じて育てる教育です。\n\nWHOが示す中心的なスキルは10項目で、自己認識、共感、批判的思考、創造的思考、意思決定、問題解決、効果的なコミュニケーション、対人関係スキル、ストレスへの対処、感情への対処です。これらは社会的スキル、思考スキル、感情スキルの三つにまとめて整理されることもあります。ロールプレイやグループ討議など、参加型の学習方法をとるのが特徴です。\n\n日本では、喫煙・飲酒・薬物乱用の防止教育や、心の健康教育、性に関する指導などで活用されてきました。誘いを断る場面を練習するなど、知識を行動につなげる点が強みです。薬物使用への対策では効果が報告される一方、効果の検証には今後も研究が必要とされています。ソーシャルスキルトレーニングや社会性と情動の学習とも重なる、予防的な生徒指導の方法です。",
