    body: "Q-U（Questionnaire-Utilities）は、早稲田大学の河村茂雄が開発した「楽しい学校生活を送るためのアンケート」で、児童生徒一人ひとりの学校生活での満足感と意欲、そして学級集団の状態を把握できる調査です。教師の評価ではなく、児童生徒理解と学級経営の方針をつかむための資料として位置づけられています。\n\n中心となる「学級満足度尺度」は、承認得点（自分の存在や行動が級友や教師に認められているか）と被侵害得点（いじめや悪ふざけ、不適応感を受けていないか）の二軸で構成されます。これにより、学級生活満足群、非承認群、侵害行為認知群、学級生活不満足群などに分類され、とくに不満足群は不登校やいじめの被害の危険が高いとされます。個々の結果を全体にプロットすると、満足型、管理型、なれあい型といった学級集団のタイプがつかめます。\n\n学級経営の改善にも使われます。満足型学級は、管理型やなれあい型に比べて、いじめの発生率が低いことが示されています。実施後は結果を個別面談や学級づくりの見直しに結びつけることが大切で、点数だけでレッテルを貼らないよう配慮が必要です。ソシオメトリーや集団力学の考え方にも通じる、予防的な生徒指導の道具です。",
    relatedSlugs: ["sociometry-moreno", "seito-rikai", "ijime-boshi", "lewin-group-dynamics"],
    isCanonical: true,
