    body: "課題予防的生徒指導は、改訂版生徒指導提要において重層的支援構造の基盤となる一次支援として位置づけられる。特定の問題行動が生じた後の事後対応ではなく、全生徒を対象として学校適応を支え、困難の発生を未然に防止することを目的とする。\n\n学校現場では、学級担任を中心とした温かい学級経営を基盤に、教科指導における協働的な学びの創出や、特別活動を通じた自律的な集団活動が実践される。教職員全員が共通の指導目標を共有し、居場所と所属感を実感できる受容的な集団づくりを進める。\n\n全生徒への日常的な関わりを深めることは、児童生徒の自己存在感や自己有用感を高め、自発的に判断し行動する自己指導能力を育む。安心できる学級集団の中で良好な関係を育てる体験は、いじめや孤立を未然に防ぎ、学校生活の充実をもたらす。",
