    body: "不登校児童生徒の自立支援は、教育機会確保法の理念や文部科学省の指針に基づき推進される方針である。不登校を個人の問題や怠惰と捉えるのではなく、誰にでも起こり得るものとして理解し、無理な登校刺激を避け、将来の社会的自立を保障することを目的とする。\n\n支援体制では、学級担任や教育相談担当が保護者と信頼関係を築き、家庭訪問や定期的な情報共有を丁寧に行う。教育支援センターやフリースクール、校内教育支援センター等の多様な場を活用し、本人のペースに合わせた学習支援や生活相談を整える。\n\n安心できる居場所で自己理解を深め、自己肯定感を回復させることは、児童生徒が自発的に進路を選択する自己指導能力を育む。多様な学習機会を保障することで、孤立を防ぎ、社会の中で自分らしく生き抜く力を育成する教育的意義を持つ。",
