    body: "睡眠リズム障害への指導は、生徒指導提要や学校保健安全計画において、生徒の心身の健康と学校適応を保障するための重要な課題として位置づけられる。情報端末の長時間利用や起立性調節障害などを背景に乱れた体内時計の乱れを、生徒指導と保健の連携により支援する。\n\n支援体制では、養護教諭や学級担任が睡眠記録表などを活用して日々の生活実態を把握する。スクールカウンセラーによる心理支援に加え、必要に応じて専門の医療機関と連携し、日中の光浴びや段階的な就寝時間の調整など具体的な生活改善手順を助言する。\n\n自らの生活リズムを自律的に整える経験は、生徒の自己管理能力や自己指導能力を高める上で大きな教育的価値を持つ。健康な生活習慣の回復は、集中力や情緒の安定を取り戻させ、学力不振や登校困難を未然に防止し、充実した学校生活の基盤を築く。",
