    body: "身体的虐待の痕跡確認と養護教諭の初期対応とは、児童生徒の身体に残された傷や不自然な外傷を保健室の機能を生かして早期に発見する実践である。生徒指導提要や虐待対応指針に基づき、養護教諭は児童の心身の異常を専門的に把握し、学校の組織対応を始動させる中核的役割を担っている。\n\n保健室来室時や定期健康診断の機会を捉え、衣服に隠れた不自然な打撲痕や火傷の痕跡を児童に過度な負担をかけずに観察・記録する。虐待が疑われる場合は直ちに管理職へ報告し、生徒指導主事や担任と情報を集約した上で、速やかに児童相談所へ通告し警察等の関係機関とも連携する。\n\n保健室という安全で受容的な空間において苦痛を受け止めることは、傷ついた児童生徒に強い安心感をもたらし恐怖心を和らげる。早期の保護と継続的な見守り体制を確立することは、生命の危機を未然に回避し、子どもが自己肯定感を回復していくための不可欠な教育的支援となる。",
