    body: "動機づけ面接法とは、生徒指導提要における自己指導能力の育成を目指し、児童生徒自身の内発的な変化への動機を高める協働的な対話アプローチである。非行や怠惰、不規則な生活習慣を頭ごなしに厳しくとがめるのではなく、本人が抱える「変わりたい」という思いと現状維持の葛藤を丁寧に引き出す。\n\n指導手順としては、開かれた質問、肯定、傾聴、要約という基本技法を用いながら、生徒の言葉の中から変化を志向する発言を捉えて焦点化する。スクールカウンセラーや学級担任が受容的な態度で面談を重ね、変化に対する両価的な感情を整理し、本人が自ら実現可能な目標を設定できるよう伴走する。\n\n指示待ちや反発ではなく、自らの意志で行動を決定して改善に取り組む自立の力を育てる教育的意義がある。受容された経験を通じて生徒は自己肯定感を高め、教員との間に深い信頼関係を築くことで学校が安心の居場所となる。",
