    body: "ナラティヴ・セラピーとは、教育相談や生徒指導において、問題と人間を分離して捉える「問題の外在化」を軸とした心理援助理論である。「怠け者の生徒」「怒りっぽい子」と個人の性格に問題を帰属させるのではなく、生徒を悩ませている問題を外在的な存在として言語化し、対立関係を解消する。\n\n面談の場では、スクールカウンセラーや教員が生徒とともに「イライラ虫が暴れるとき」といった表現で問題に名前を付け、問題が生徒に与える影響や、逆に生徒が問題に打ち勝てた例外的な場面を探求する。多職種チームでこの肯定的な語りを共有し、生徒の小さな主体的な行動を学校全体で承認する。\n\nレッテル貼りから解放された児童生徒が自己効力感を取り戻し、自らの人生の主人公として歩む自己指導能力を育む意義を持つ。教室や学校が自分をありのままに受容してくれる安全な居場所となり、問題行動の未然防止へと結実する。",
