    body: "ミラクル・クエスチョンとは、生徒指導提要でも推奨される解決志向ブリーフセラピーの中核をなす代表的な質問技法である。過去の原因追及や失敗の分析に終始するのではなく、「今夜眠っている間に奇跡が起き、問題がすべて解決したとしたら」と問いかけることで、望ましい未来の姿を鮮明に描かせる。\n\n実践においては、朝目覚めたときの周囲の変化や自分自身の行動の違いを細部まで対話によって具体化していく。学級担任や相談担当教員は、生徒が語る理想の未来の中に、現在すでにできている小さな行動の芽を見出し、今日から実行できる身近な第一歩へと落とし込む。\n\n児童生徒が自分には困難を乗り越える力があるという自信を回復し、未来志向で行動を選択する自己指導能力を育む教育的価値を持つ。前向きな目標を持つことで学級での居場所感が深まり、不適応行動や無気力の未然防止につながる。",
