    body: "スケーリング・クエスチョンとは、解決志向アプローチに基づき、児童生徒の主観的な気持ちや目標達成度を数値で表現させる技法である。生徒指導提要が示す児童生徒理解の深化に寄与し、白黒思考や全か無かの極端な捉え方に陥りがちな生徒に、変化の連続性や進歩の存在を自覚させる背景を持つ。\n\n面談では、「最悪の状態を一点、理想を十点とすると、今の気分は何点か」と尋ね、現状の点数と評価した理由を深掘りする。教員やカウンセラーは「なぜ零点ではなく三点なのか」を問いかけて本人の努力や強みを見出し、次に「点を一つ上げるために何ができるか」を協働して具体化する。\n\n児童生徒が自分の成長や変化のプロセスを実感し、実行可能な小さな目標を自律的に設定する自己指導能力を育てる。数値を用いた客観的な対話は教員との安心できる信頼関係を育み、学校生活における確かな居場所感を支える。",
