    body: "例外探し技法とは、問題行動や学校不適応を示す生徒に対し、その問題が起きていない「例外」の瞬間に着目する解決志向アプローチの手法である。生徒指導提要における生徒の長所伸長や強みの活用方針に合致し、失敗の追及から脱却して成功の再現性を探る姿勢を重視する背景を持つ。\n\n指導の場面では、教員やスクールカウンセラーが生徒との対話を通じて「授業中に集中できていた時間」や「落ち着いて友達と話せた場面」を具体的に特定する。何がその違いを生み出したのかを生徒とともに分析し、学級担任や教科担当教員がその環境要因を日常の授業づくりや支援体制に反映させる。\n\n生徒自身が「自分はいつでも失敗しているわけではない」と気づき、自己効力感と自己指導能力を高める教育的意義がある。成功体験の積み重ねが学級内の居場所感を確かなものにし、反抗や孤立といった二次的課題を未然に防止する。",
