    body: "共感的一致とは、来談者中心療法の創始者ロジャーズが提唱した、援助者における自己一致と誠実さを意味する概念である。生徒指導提要における教育相談の基本的態度として位置づけられ、指導者が専門家の仮面をかぶるのではなく、一人の人間として防衛的にならず誠実かつ真剣に生徒と向き合う姿勢を指す。\n\n学校現場の実践では、教員が生徒の苦しみや怒りの言葉に対して表面的な同調やお説教で応じず、自己の感情を自覚しつつ誠実な態度で話を聴き取る。スクールカウンセラーによる教職員研修などを通じ、教員が自身の感情の揺らぎを認めながら、生徒に対してありのままの誠意を伝える面談技術を習得する。\n\n大人の真実味ある態度に触れた生徒は、安心して本音を語れる心の安全基地を見出す。虚飾のない温かな関わりが児童生徒の自尊感情を育み、自己を率直に見つめ直して主体的に生き方を整える自己指導能力の基盤となる。",
