    body: "無条件の肯定的関心とは、生徒の行動の成否や評価基準に左右されず、その人格と尊厳を丸ごと肯定的に受け止めるカウンセリングの態度である。生徒指導提要における「児童生徒の個性の尊重」と人権教育の理念に深く通底し、問題行動を起こした生徒であっても人間としての価値を損なわない基本方針を示す。\n\n指導の現場では、校則違反や学習の遅れを指摘する際にも、生徒の存在自体を否定せず、行動と人格を明確に区別して関わる。学級担任や教育相談担当教員は、生徒がどのような失敗を犯しても見捨てずに話を聴き続け、多職種チーム協働のもとで粘り強い受容的関わりを一貫して維持する。\n\n無条件に受け入れられる体験を通じて、児童生徒は深い安心感を得て自己肯定感を回復する。学校が自己の存在を保障してくれる居場所となることで、防衛的な反発や非行を予防し、他者を尊重しながら自立する自己指導能力を育む。",
