    body: "学校安全計画とは、児童生徒が安心して教育を受けられる環境を確立するため、学校保健安全法第27条に基づき各学校が毎年度策定する総合計画である。生徒指導や学校経営の根幹をなすものであり、生活安全（防犯）、交通安全、災害安全（防災）の3領域を包括し、学校安全管理と安全教育を体系的に連携させることが求められる。\n\n策定にあたっては、安全主任を中心に全教職員が関与し、施設設備の安全点検や避難訓練の年間実施計画を具体化する。さらに警察署や消防署、自治体の防災担当部局、PTA等の地域関係者と連携協議会を組織し、非常時連絡体制や合同点検の仕組みを構築する。定期的な危険予測の検証と計画の不断の見直しを行う。\n\n安全管理の徹底にとどまらず、児童生徒自身が日常の危険を正しく認識し、主体的に回避・判断できる自己安全管理能力を育成することが重要である。児童会や生徒会による安全点検活動や地域見守り活動への参加を通じて、安全で安心な学校環境を自ら築く意識を高める。",
