    body: "デートDV防止教育とは、若年層の交際関係において生じる身体的暴力、暴言や過度な束縛、通信機器の無断閲覧等の精神的・性的な暴力を未然に防ぐ指導である。配偶者暴力防止法や生徒指導提要の人権尊重の指針を基盤とし、暴力の根底にある支配や偏見の是正、対等な関係性の構築を学ぶことを目的に行われる。\n\n学校現場では、特別活動や総合的な探究の時間、道徳科等を活用し、外部専門機関やスクールソーシャルワーカーと連携した演習を展開する。具体的な事例や役割演技を通じて、交際相手の意見を尊重しつつ自分の意思も穏やかに伝える自己表現の技法を習得させ、相談機関や校内相談室の利用方法を分かりやすく指導する。\n\nこの指導は、暴力の加害者にも被害者にもならない自己指導能力と他者尊重の精神を培う。児童生徒が他者との健康な距離感を保ちながら信頼関係を深められるようになることで、安心して他者と関わり合える居場所づくりと将来の暴力被害の未然防止を支える。",
