    body: "児童養護施設等を退所する生徒への自立進学支援とは、社会的養護のもとで暮らす生徒が高校卒業や自立の段階で直面する経済的・精神的課題を解消するための進路指導施策である。児童福祉法や生徒指導提要の趣旨に則り、家庭の支援を受けられない生徒の修学機会を公的に保障し、貧困の世代間連鎖を断ち切る重要な責務と位置づけられている。\n\n学校現場では、進路指導部や学級担任がスクールソーシャルワーカーと緊密に連携し、給付型奨学金や高等教育修学支援新制度、各種基金の申請手続きを早期から組織的にサポートする。施設職員や児童相談所の担当者と定期的なケース会議を重ね、住居の確保や卒業後の生活設計を共有し、孤立させない支援網を構築する。\n\n退所者支援の本質は、経済的援助にとどまらず生徒本人が自己肯定感を回復し、困ったときに自ら助けを求められる自己指導能力を育むことにある。学校がいつでも立ち寄れる安心な居場所として機能し続けることで、社会生活での挫折や孤立を未然に防止する。",
