    body: "少年院出院生徒の復学支援とは、非行事実により矯正教育を受けた生徒が再び学校生活に復帰し、社会復帰と学び直しを達成するための生徒指導体制である。少年法および生徒指導提要の更生支援方針を背景とし、生徒の立ち直り権利を尊重しながら、再非行を防止し安心な学校生活への再適応を促す教育的介入として位置づけられる。\n\n学校現場では、生徒指導主事や校長が保護観察所や少年院の担当官、保護司と出院前からの連絡調整会議を実施する。個別の受入指導計画を作成し、学力補充の体制や教室での人間関係への配慮、心理的ケアの担当者を定める。スクールカウンセラーやソーシャルワーカーとも連携し、秘密保持を厳格に管理しながら生徒を多職種チームで支える。\n\n復学支援の要は、生徒が過ちを乗り越えて自律的な行動規範と将来の目標を再構築する自己指導能力を育むことにある。教職員や学級集団が偏見なく受容し、努力を肯定的に評価する居場所をつくることで、生徒の自己肯定感を高め再非行を未然に防止する。",
