    body: "児童自立支援施設入所生徒との連携指導とは、不良行為や家庭環境の困難により施設へ入所措置となった児童生徒に対し、学校教育の連続性を維持しながら自立を支援する協働体制である。児童福祉法や学校教育法施行令に根拠を持ち、生徒指導提要においても原在籍校と施設併設校等との間で継続的・組織的な支援を行うことが規定されている。\n\n現場では、原在籍校の教員と施設の生活支援員や教員が指導要録の引き継ぎ、指導記録や生活状況の定期共有を綿密に行う。ケース会議を通じて生徒の心理状態や学力定着度、家庭環境の改善状況を把握し、一時帰宅時や復校に向けた段階的な体験交流を計画する。スクールソーシャルワーカーも加わり福祉と学校をつなぐ連絡調整を担う。\n\n継続的な連携の意義は、生徒がどこにいても見守られているという安心感と信頼関係を保持することにある。生活規律の回復と自己統制力、すなわち自己指導能力の向上を支え、退所後の円滑な学校復帰や社会的自立への移行を確かなものにする。",
