    body: "メンタルヘルス・リテラシー教育とは、心の健康やストレスへの対処法、精神疾患に関する科学的な正しい知識を体系的に教える学校教育実践である。新学習指導要領の保健体育科において精神疾患の予防と回復が盛り込まれたことや、生徒指導提要における一次支援（課題予防的生徒指導）の重点化を背景に、全国の学校で推進されている。\n\n授業展開では、養護教諭や保健体育科教員が連携し、心の病気の初期サイン、ストレスへの気づきと呼吸法等の技法を扱う。心の不調は誰にでも生じる自然な反応であることを強調して偏見を取り除き、一人で悩まずに教員やスクールカウンセラー、公的相談窓口に助けを求める「援助要請行動」の具体的方法を指導する。\n\n正しい知識の習得は、自らの心の状態を観察し健康を主体的に管理する自己指導能力を培う。さらに、友達の不調に気づいて温かく声をかけたり専門家につないだりする互助の風土を学級内に生み出し、自殺や不登校の未然防止に決定的な効果をもたらす。",
