    body: "教員のメンタルヘルス維持とバーンアウト予防とは、困難な生徒指導事案や多忙化による教員の心理的消耗を防ぎ、持続可能な学校指導体制を保つための管理施策である。生徒指導提要では教員の指導力向上とともに過重負担の軽減が明記されており、教員の心の健康が児童生徒への安全で質の高い生徒指導に不可欠な前提として位置づけられている。\n\n学校現場では、問題行動の指導を担任ひとりに抱え込ませず、生徒指導主事や管理職、スクールカウンセラー、スクールソーシャルワーカーが協働する「チーム学校」体制を徹底する。定期的なストレス点検や校内面談を実施し、教職員相互の日常的な声かけや相談しやすい職員室風土を醸成する。校務支援システムによる事務効率化も推進する。\n\n教員自身が心身の余裕と安心感を取り戻すことは、児童生徒に対する温かく受容的な指導姿勢を育む土台となる。大人が笑顔で支える健全な学校環境こそが、児童生徒の安心できる居場所となり、豊かな自己指導能力の育成と学級の荒れの未然防止につながる。",
