    body: "多層指導モデルMIMとは、児童の読みのつまずきを早期に発見し、学級全体への良質な指導から小集団・個別の集中支援へと段階的に支援を強めていく科学的指導法である。米国の支援モデルを参考に開発され、生徒指導提要における一次支援から三次支援へと連動する予防的生徒指導の理念を体現している。\n\n学校現場では、小学校低学年を対象に特殊音節（促音や長音、よう音）の読み書き検査を定期実施し、習得状況を客観的に把握する。通常学級での工夫された全体指導（第1層）を実施し、成果が不十分な児童には少人数での補充指導（第2層）、通級指導や個別の特別支援（第3層）を組織的に提供する。担任と特別支援教育教員が緊密に連携する。\n\n学習上のつまずきを早期に解消することは、児童の自己効力感と学習意欲を高め、学習遅滞から派生する不登校や問題行動を根本から予防する。成功体験の積み重ねが児童の主体的な学びと自己指導能力を育み、学校生活における確かな居場所づくりに貢献する。",
