    body: "学校復帰にとらわれない社会的自立支援の指針とは、不登校児童生徒への支援において単なる登校再開を唯一の目標とせず、生徒の社会的自立を最優先に位置づける基本理念である。2019年の文部科学省通知や教育機会確保法、生徒指導提要および国の総合対策方針に明確に規定されており、不登校支援の歴史的転換点を示している。\n\n学校現場では、児童生徒の休養の必要性を認めつつ、教育支援センター（適応指導教室）や特例校、民間支援施設、情報通信技術を活用した自宅学習など多様な学習機会を柔軟に提案・連携する。担任やスクールカウンセラー、ソーシャルワーカーが協働して居場所を確保し、指導要録上の出席扱い措置や進路情報の丁寧な提供を組織的に行う。\n\nこの指針の本質は、児童生徒が自責の念から解放され、自己肯定感を回復しながら自らの進路を切り拓く自己指導能力を培うことにある。孤立を防ぎ多様な選択肢を保障することで、児童生徒が安心して社会へ羽ばたける息の長い支援網を形成する。",
